<script setup>
import { computed, ref } from 'vue'; import { Head } from '@inertiajs/vue3'; import PublicLayout from '../Layouts/PublicLayout.vue'; import PageContainer from '../Components/Layout/PageContainer.vue'; import BaseCard from '../Components/Base/BaseCard.vue'; import BaseModal from '../Components/Base/BaseModal.vue'; import LazyImage from '../Components/Base/LazyImage.vue';
const props = defineProps({ events: Array }); const order = ref('newest'); const preview = ref(null);
const sortedEvents = computed(() => [...props.events].sort((a, b) => (order.value === 'newest' ? 1 : -1) * (new Date(b.event_date) - new Date(a.event_date))));
const dateLabel = (value) => value ? new Intl.DateTimeFormat('id-ID', { dateStyle: 'long' }).format(new Date(value)) : '[PLACEHOLDER: Tanggal event]';
</script>
<template><Head title="Galeri Event"><meta name="description" content="[PLACEHOLDER: Meta description Galeri Event]" /></Head><PublicLayout><section class="relative overflow-hidden bg-[#f5f8fc] py-16 text-center lg:py-20"><span class="absolute -left-32 -top-32 h-64 w-64 rounded-full bg-[#0052c8]/10"></span><span class="absolute -right-24 bottom-0 h-56 w-56 rounded-full bg-[#f6b400]/15 blur-xl"></span><PageContainer><h1 class="relative font-heading text-4xl font-bold text-[#0052c8] lg:text-5xl">Galeri Event</h1><p class="relative mx-auto mt-4 max-w-2xl text-sm leading-6 text-[#414753]">[PLACEHOLDER: Deskripsi resmi dokumentasi event Kampoeng Radja]</p></PageContainer></section><section class="bg-[#f8f9fb] pb-16"><PageContainer><div class="flex h-[70px] items-center justify-between border-b border-[#e1e2eb]"><p class="text-xs font-semibold text-[#414753]">↕ Urutkan dokumentasi event</p><div class="inline-flex gap-2"><button :class="order === 'newest' ? 'bg-[#004e9f] text-white' : 'border border-[#cbd3df] text-[#414753]'" class="h-9 rounded-lg px-4 text-xs font-semibold" @click="order = 'newest'">Terbaru</button><button :class="order === 'oldest' ? 'bg-[#004e9f] text-white' : 'border border-[#cbd3df] text-[#414753]'" class="h-9 rounded-lg px-4 text-xs font-semibold" @click="order = 'oldest'">Terlama</button></div></div><div v-if="sortedEvents.length" class="mt-5 space-y-8"><BaseCard v-for="event in sortedEvents" :key="event.id" class="p-6 lg:p-10"><h2 class="font-heading text-2xl text-[#002147]">{{ event.title }}</h2><p class="mt-2 text-sm font-semibold text-[#0052c8]">{{ dateLabel(event.event_date) }}</p><div v-if="event.photos.length" class="mt-5 grid grid-cols-2 gap-4 lg:grid-cols-4"><button v-for="photo in event.photos" :key="photo.id" @click="preview = { photo, event }"><LazyImage :src="photo.photo_path" :alt="photo.alt_text || event.title" class-name="h-40 w-full rounded-lg object-cover lg:h-[180px]" /></button></div><div v-else class="mt-5 grid grid-cols-2 gap-4 lg:grid-cols-4"><div v-for="item in 4" :key="item" class="grid h-40 place-items-center rounded-lg bg-[#eef2f7] text-xs text-[#6b7280]">[PLACEHOLDER: Foto event]</div></div><p class="mx-auto mt-8 max-w-4xl rounded-md bg-[#f5f7fa] p-5 text-center text-sm leading-6 text-[#414753]">{{ event.description || '[PLACEHOLDER: Deskripsi event belum tersedia]' }}</p></BaseCard></div><BaseCard v-else class="mt-5 p-10 text-center"><p class="font-heading text-2xl text-[#002147]">Dokumentasi event belum tersedia</p><p class="mt-2 text-sm text-[#414753]">[PLACEHOLDER: Tim perlu menyediakan judul, tanggal, deskripsi, dan foto event.]</p></BaseCard></PageContainer></section><BaseModal :open="Boolean(preview)" :title="preview?.event?.title || 'Foto event'" @close="preview = null"><LazyImage :src="preview?.photo?.photo_path" :alt="preview?.photo?.alt_text || preview?.event?.title || ''" class-name="max-h-[60vh] w-full rounded-xl object-contain" /><p class="mt-4 text-neutral-gray">{{ preview?.event?.description || '[PLACEHOLDER: Deskripsi event belum tersedia]' }}</p></BaseModal></PublicLayout></template>
